  return (
    <g role="button" tabIndex="0" aria-label={`fixture Id ${fixture.fixtureType}`} data-thrallo-control="ctl_804f503f" onClick={onSelect} onKeyDown={(event) => event.key === "Enter" && onSelect()} transform={`translate(${fixture.x || 0} ${fixture.y || 0}) rotate(${fixture.rotation || 0})`}>
      <circle r="24" fill={selected ? "#f59e0b" : "#fde68a"} stroke={selected ? "#0f172a" : "#92400e"} strokeWidth="3" opacity={opacity} />
