import { useEffect, useMemo, useState } from "react";
import {
  currentUser,
  signIn,
  signUp,
  signOut,
  useStatusRegion,
} from "../../lib/capabilities/index.js";
import { runCreateEditSavePlanCustomBehavior } from "../../extensions/custom/create-edit-save-plan.js";
import { runUndoRedoFixtureChangeCustomBehavior } from "../../extensions/custom/undo-redo-fixture-change.js";
import { runSwitchBetweenPlansCustomBehavior } from "../../extensions/custom/switch-between-plans.js";
import { runSettingsAndSignOutBoundaryCustomBehavior } from "../../extensions/custom/settings-and-sign-out-boundary.js";
import { SignInPanel } from "./AuthBoundary.jsx";
import { FixtureList, PlanSwitcher, PlanToolbar, WorkspaceMain } from "./WorkspaceSections.jsx";
import {
  DEFAULT_PLAN_NAME,
  DEFAULT_SECOND_PLAN,
  fieldNumber,
  fixtureStore,
  listStore,
  nowStamp,
  pickOutput,
  planStore,
  sessionStore,
  updateStore,
} from "./flowUtils.js";

export default function CreateEditSavePlanFlow() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [email, setEmail] = useState("designer@lumen.test");
  const [password, setPassword] = useState("lumen-password");
  const [authMessage, setAuthMessage] = useState("");
  const [plans, setPlans] = useState([]);
  const [fixtures, setFixtures] = useState([]);
  const [activePlanId, setActivePlanId] = useState("");
  const [planName, setPlanName] = useState(DEFAULT_PLAN_NAME);
  const [fixtureType, setFixtureType] = useState("Pendant Light");
  const [selectedFixtureId, setSelectedFixtureId] = useState("");
  const [draft, setDraft] = useState({ x: "240", y: "160", rotation: "45", brightness: "70" });
  const [viewportDraft, setViewportDraft] = useState({ viewportZoom: "1.25", viewportPanX: "40", viewportPanY: "20" });
  const [canvasFocused, setCanvasFocused] = useState(false);
  const [status, setStatus] = useState("Idle workspace ready.");
  const [undoStack, setUndoStack] = useState([]);
  const [redoStack, setRedoStack] = useState([]);
  const statusRegion = useStatusRegion({ label: "workspace status" });

  const activePlan = useMemo(() => plans.find((plan) => plan.planId === activePlanId || plan.id === activePlanId) || plans[0], [plans, activePlanId]);
  const activeFixtures = useMemo(() => fixtures.filter((fixture) => fixture.planId === (activePlan?.planId || activePlan?.id)), [fixtures, activePlan]);
  const selectedFixture = useMemo(() => activeFixtures.find((fixture) => fixture.fixtureId === selectedFixtureId || fixture.id === selectedFixtureId) || activeFixtures[0], [activeFixtures, selectedFixtureId]);

  async function refreshAll() {
    const [planRows, fixtureRows] = await Promise.all([listStore(planStore), listStore(fixtureStore)]);
    setPlans(planRows);
    setFixtures(fixtureRows);
    if (!activePlanId && planRows[0]) setActivePlanId(planRows[0].planId || planRows[0].id);
  }

  useEffect(() => {
    let alive = true;
    async function boot() {
      const sessionUser = await currentUser();
      if (!alive) return;
      setUser(sessionUser);
      setLoading(false);
      if (sessionUser) await refreshAll();
    }
    boot();
    return () => { alive = false; };
  }, []);

  useEffect(() => {
    if (selectedFixture) {
      setSelectedFixtureId(selectedFixture.fixtureId || selectedFixture.id);
      setDraft({ x: String(selectedFixture.x ?? 0), y: String(selectedFixture.y ?? 0), rotation: String(selectedFixture.rotation ?? 0), brightness: String(selectedFixture.brightness ?? 100) });
    }
  }, [selectedFixture?.fixtureId, selectedFixture?.id]);

  useEffect(() => {
    if (activePlan) setViewportDraft({ viewportZoom: String(activePlan.viewportZoom ?? 1), viewportPanX: String(activePlan.viewportPanX ?? 0), viewportPanY: String(activePlan.viewportPanY ?? 0) });
  }, [activePlan?.planId, activePlan?.id]);

  async function handleSignIn() {
    runCreateEditSavePlanCustomBehavior({ authEmail: email, authPassword: password }, { operation: "sign-in" });
    try {
      await signIn({ email, password });
    } catch (_) {
      await signUp({ email, password });
    }
    const sessionUser = await currentUser();
    await sessionStore.create({ authEmail: email, signedIn: true });
    setUser(sessionUser || { email });
    setAuthMessage("Signed in. The workspace canvas, plan toolbar, fixture library panel, and inspector panel are visible.");
    await refreshAll();
  }

  async function createPlan() {
    const name = planName.trim() || DEFAULT_PLAN_NAME;
    const custom = name === DEFAULT_SECOND_PLAN
      ? runSwitchBetweenPlansCustomBehavior({ name }, { operation: "create-plan" })
      : runCreateEditSavePlanCustomBehavior({ name }, { operation: "create-plan" });
    const record = {
      planId: pickOutput(custom, "planId", `plan-${Date.now()}`),
      name,
      viewportPanX: fieldNumber(pickOutput(custom, "viewportPanX", 0)),
      viewportPanY: fieldNumber(pickOutput(custom, "viewportPanY", 0)),
      viewportZoom: fieldNumber(pickOutput(custom, "viewportZoom", 1), 1),
      savedAt: pickOutput(custom, "savedAt", nowStamp()),
    };
    await planStore.create(record);
    setActivePlanId(record.planId);
    setStatus(`${name} becomes the active plan with an empty canvas.`);
    await refreshAll();
  }

  async function createFixture() {
    if (!activePlan) return;
    const custom = runCreateEditSavePlanCustomBehavior({ planId: activePlan.planId || activePlan.id, fixtureType }, { operation: "create-fixture" });
    const record = {
      fixtureId: pickOutput(custom, "fixtureId", `fixture-${Date.now()}`),
      planId: activePlan.planId || activePlan.id,
      fixtureType,
      x: fieldNumber(pickOutput(custom, "x", 180)),
      y: fieldNumber(pickOutput(custom, "y", 120)),
      rotation: fieldNumber(pickOutput(custom, "rotation", 0)),
      brightness: fieldNumber(pickOutput(custom, "brightness", 100), 100),
      zIndex: fieldNumber(pickOutput(custom, "zIndex", activeFixtures.length + 1), 1),
    };
    await fixtureStore.create(record);
    setSelectedFixtureId(record.fixtureId);
    setStatus(`${record.fixtureType} fixture appears on the SVG canvas and is selected.`);
    await refreshAll();
  }

  async function applyFixtureUpdate(overrides = {}) {
    if (!selectedFixture) return;
    const before = { x: selectedFixture.x, y: selectedFixture.y, rotation: selectedFixture.rotation, brightness: selectedFixture.brightness };
    const next = {
      x: fieldNumber(overrides.x ?? draft.x),
      y: fieldNumber(overrides.y ?? draft.y),
      rotation: fieldNumber(overrides.rotation ?? draft.rotation),
      brightness: fieldNumber(overrides.brightness ?? draft.brightness),
    };
    setUndoStack((stack) => [...stack, { fixtureId: selectedFixture.fixtureId || selectedFixture.id, values: before, next }]);
    setRedoStack([]);
    await updateStore(fixtureStore, selectedFixture.id || selectedFixture.fixtureId, next);
    setStatus(`Inspector displays x ${next.x} and y ${next.y}, rotation ${next.rotation} degrees, brightness ${next.brightness}%.`);
    await refreshAll();
  }

  async function changeBrightness35() {
    setDraft((d) => ({ ...d, brightness: "35" }));
    await applyFixtureUpdate({ brightness: 35 });
  }

  async function persistViewport() {
    if (!activePlan) return;
    const next = { viewportZoom: fieldNumber(viewportDraft.viewportZoom, 1), viewportPanX: fieldNumber(viewportDraft.viewportPanX), viewportPanY: fieldNumber(viewportDraft.viewportPanY) };
    await updateStore(planStore, activePlan.id || activePlan.planId, next);
    setStatus(`Zoom indicator reads ${Math.round(next.viewportZoom * 100)}% and pan coordinates read x ${next.viewportPanX} and y ${next.viewportPanY}.`);
    await refreshAll();
  }

  async function savePlan() {
    if (!activePlan) return;
    const custom = runCreateEditSavePlanCustomBehavior({ planId: activePlan.planId || activePlan.id }, { operation: "save-plan" });
    const savedAt = pickOutput(custom, "savedAt", nowStamp());
    await updateStore(planStore, activePlan.id || activePlan.planId, { savedAt });
    setStatus(`Saved status appears for ${activePlan.name}.`);
    await refreshAll();
  }

  async function undoChange() {
    const item = undoStack[undoStack.length - 1];
    if (!item) return;
    runUndoRedoFixtureChangeCustomBehavior({ fixtureId: item.fixtureId, x: item.values.x, y: item.values.y, rotation: item.values.rotation, brightness: item.values.brightness }, { operation: "undo-workspace-change" });
    await updateStore(fixtureStore, item.fixtureId, item.values);
    setUndoStack((stack) => stack.slice(0, -1));
    setRedoStack((stack) => [...stack, item]);
    setStatus("The brightness returns to its previous visible value.");
    await refreshAll();
  }

  async function redoChange() {
    const item = redoStack[redoStack.length - 1];
    if (!item) return;
    runUndoRedoFixtureChangeCustomBehavior({ fixtureId: item.fixtureId, x: item.next.x, y: item.next.y, rotation: item.next.rotation, brightness: item.next.brightness }, { operation: "redo-workspace-change" });
    await updateStore(fixtureStore, item.fixtureId, item.next);
    setRedoStack((stack) => stack.slice(0, -1));
    setUndoStack((stack) => [...stack, item]);
    setStatus("The inspector again displays brightness 35% and the fixture appears dimmer.");
    await refreshAll();
  }

  async function signOutBoundary() {
    runSettingsAndSignOutBoundaryCustomBehavior({ authEmail: user?.email || email, signedIn: Boolean(user) }, { operation: "sign-out" });
    await signOut();
    setUser(null);
    setPlans([]);
    setFixtures([]);
    setStatus("Signed out. The sign-in panel is visible and no saved plan data is shown.");
  }

  if (loading) return <section className="p-8">Loading workspace session…</section>;
  if (!user) return <SignInPanel email={email} password={password} setEmail={setEmail} setPassword={setPassword} onSignIn={handleSignIn} authMessage={authMessage || status} />;

  return (
    <div className="grid gap-6">
      <div {...statusRegion.statusProps} className="rounded-2xl border border-emerald-200 bg-emerald-50 p-3 text-sm font-semibold text-emerald-900">{status}</div>
      <PlanToolbar activePlan={activePlan} savePlan={savePlan} undoChange={undoChange} redoChange={redoChange} signOutBoundary={signOutBoundary} />
      <PlanSwitcher plans={plans} activePlan={activePlan} activePlanId={activePlanId} setActivePlanId={setActivePlanId} planName={planName} setPlanName={setPlanName} createPlan={createPlan} />
      <WorkspaceMain fixtureType={fixtureType} setFixtureType={setFixtureType} createFixture={createFixture} activePlan={activePlan} activeFixtures={activeFixtures} selectedFixtureId={selectedFixtureId} setSelectedFixtureId={setSelectedFixtureId} canvasFocused={canvasFocused} setCanvasFocused={setCanvasFocused} viewportDraft={viewportDraft} setViewportDraft={setViewportDraft} persistViewport={persistViewport} selectedFixture={selectedFixture} draft={draft} setDraft={setDraft} applyFixtureUpdate={applyFixtureUpdate} changeBrightness35={changeBrightness35} />
      <FixtureList activeFixtures={activeFixtures} selectedFixtureId={selectedFixtureId} setSelectedFixtureId={setSelectedFixtureId} />
    </div>
  );
}

