import { entityStore } from "../../lib/capabilities/composed/crud.js";

export const planStore = entityStore("plan");
export const fixtureStore = entityStore("fixture");
export const sessionStore = entityStore("authSession");

export const FIXTURE_TYPES = ["Pendant Light", "Track Head", "Wall Washer"];
export const DEFAULT_PLAN_NAME = "Atrium Lighting Plan";
export const DEFAULT_SECOND_PLAN = "Gallery Track Plan";

export function nowStamp() {
  return new Date().toISOString();
}

export function fieldNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function pickOutput(result, key, fallback) {
  return result?.[key] ?? result?.[`create-edit-save-plan.custom.${key}`] ?? result?.[`switch-between-plans.custom.${key}`] ?? result?.[`undo-redo-fixture-change.custom.${key}`] ?? fallback;
}

export async function listStore(store) {
  const result = await store.list();
  return Array.isArray(result) ? result : result?.items || result?.records || [];
}

export async function updateStore(store, id, patch) {
  if (!id) return null;
  return store.update(id, patch);
}

