import { useSemanticAction } from "../../lib/capabilities/index.js";
import { CanvasPanel } from "./CanvasPanel.jsx";
import { Inspector } from "./Inspector.jsx";
import { FIXTURE_TYPES, DEFAULT_PLAN_NAME } from "./flowUtils.js";

export function PlanToolbar({ activePlan, savePlan, undoChange, redoChange, signOutBoundary }) {
  const saveAction = useSemanticAction({ name: "save-plan", label: "save control", onActivate: savePlan });
  const undoAction = useSemanticAction({ name: "undo-workspace-change", label: "undo control", onActivate: undoChange });
  const redoAction = useSemanticAction({ name: "redo-workspace-change", label: "redo control", onActivate: redoChange });
  const signOutAction = useSemanticAction({ name: "sign-out", label: "sign-out", onActivate: signOutBoundary });

  return (
    <header className="rounded-3xl bg-slate-950 p-6 text-white shadow-xl" aria-label="plan toolbar">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div><p className="text-sm uppercase tracking-[0.3em] text-amber-300">Plan toolbar</p><h1 className="text-3xl font-bold">{activePlan?.name || "Create a plan"}</h1><p className="text-slate-300">Saved at {activePlan?.savedAt || "not yet saved"}</p></div>
        <div className="flex flex-wrap gap-2">
          <button {...saveAction.buttonProps} data-thrallo-action="act_5ff55ad8" className="rounded-xl bg-emerald-500 px-4 py-2 font-bold text-slate-950">save control</button>
          <button {...undoAction.buttonProps} data-thrallo-action="act_d6a739ca" className="rounded-xl bg-white/10 px-4 py-2 font-bold">undo control</button>
          <button {...redoAction.buttonProps} data-thrallo-action="act_5006323c" className="rounded-xl bg-white/10 px-4 py-2 font-bold">redo control</button>
          <button {...signOutAction.buttonProps} className="rounded-xl border border-white/30 px-4 py-2 font-bold">Sign out</button>
        </div>
      </div>
    </header>
  );
}

export function PlanSwitcher({ plans, activePlan, activePlanId, setActivePlanId, planName, setPlanName, createPlan }) {
  const createPlanAction = useSemanticAction({ name: "create-plan", label: "new plan control", onActivate: createPlan });

  return (
    <section className="grid gap-4 rounded-3xl border border-slate-200 bg-white p-5" aria-label="new plan control">
      <div className="flex flex-wrap gap-3">
