const DEFAULT_PLAN_VALUES = Object.freeze({
  viewportPanX: 0,
  viewportPanY: 0,
  viewportZoom: 1,
});

const DEFAULT_FIXTURE_VALUES = Object.freeze({
  x: 160,
  y: 120,
  rotation: 0,
  brightness: 100,
  zIndex: 1,
});

function compactId(prefix) {
  const randomPart = Math.random().toString(36).slice(2, 9);
  const timePart = Date.now().toString(36);
  return `${prefix}-${timePart}-${randomPart}`;
}

function firstValue(source, keys, fallback = undefined) {
  for (const key of keys) {
    if (source && source[key] !== undefined && source[key] !== null && source[key] !== "") {
      return source[key];
    }
  }
  return fallback;
}

function toNumber(value, fallback) {
  if (value === undefined || value === null || value === "") {
    return fallback;
  }
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function timestamp() {
  return new Date().toISOString();
}

function operationFrom(context) {
  return context?.operation || context?.operationId || "";
}

function planOutput(inputs) {
  const savedAt = firstValue(inputs, ["savedAt", "create-edit-save-plan.custom.savedAt"], timestamp());
  const planId = firstValue(inputs, ["planId", "create-edit-save-plan.custom.planId"], compactId("plan"));
  const name = firstValue(inputs, ["name", "create-edit-save-plan.draft.name"], "Untitled lighting plan");

  return {
    planId,
    name,
    viewportPanX: toNumber(firstValue(inputs, ["viewportPanX", "create-edit-save-plan.custom.viewportPanX"]), DEFAULT_PLAN_VALUES.viewportPanX),
    viewportPanY: toNumber(firstValue(inputs, ["viewportPanY", "create-edit-save-plan.custom.viewportPanY"]), DEFAULT_PLAN_VALUES.viewportPanY),
    viewportZoom: toNumber(firstValue(inputs, ["viewportZoom", "create-edit-save-plan.custom.viewportZoom"]), DEFAULT_PLAN_VALUES.viewportZoom),
    savedAt,
  };
}

function fixtureOutput(inputs) {
  const planId = firstValue(inputs, ["planId", "create-edit-save-plan.draft.planId", "create-edit-save-plan.custom.planId"], "");
  const fixtureType = firstValue(inputs, ["fixtureType", "create-edit-save-plan.draft.fixtureType", "create-edit-save-plan.custom.fixtureType"], "Pendant Light");
  const fixtureId = firstValue(inputs, ["fixtureId", "create-edit-save-plan.draft.fixtureId", "create-edit-save-plan.custom.fixtureId"], compactId("fixture"));

  return {
    fixtureId,
    planId,
    fixtureType,
    x: toNumber(firstValue(inputs, ["x", "create-edit-save-plan.draft.x", "create-edit-save-plan.custom.x"]), DEFAULT_FIXTURE_VALUES.x),
    y: toNumber(firstValue(inputs, ["y", "create-edit-save-plan.draft.y", "create-edit-save-plan.custom.y"]), DEFAULT_FIXTURE_VALUES.y),
    rotation: toNumber(firstValue(inputs, ["rotation", "create-edit-save-plan.draft.rotation", "create-edit-save-plan.custom.rotation"]), DEFAULT_FIXTURE_VALUES.rotation),
    brightness: toNumber(firstValue(inputs, ["brightness", "create-edit-save-plan.draft.brightness", "create-edit-save-plan.custom.brightness"]), DEFAULT_FIXTURE_VALUES.brightness),
    zIndex: toNumber(firstValue(inputs, ["zIndex", "create-edit-save-plan.draft.zIndex", "create-edit-save-plan.custom.zIndex"]), DEFAULT_FIXTURE_VALUES.zIndex),
  };
}

export function runCreateEditSavePlanCustomBehavior(inputs = {}, context = {}) {
  const operation = operationFrom(context);

  if (operation === "sign-in") {
    const authEmail = String(firstValue(inputs, ["authEmail", "create-edit-save-plan.draft.authEmail"], "")).trim();
    return {
      authEmail,
      signedIn: Boolean(authEmail),
      durable: {
        record: authEmail ? { authEmail, signedIn: true } : null,
        reference: authEmail || null,
      },
    };
  }

  if (operation === "create-plan") {
    const plan = planOutput(inputs);
    return {
      ...plan,
      durable: {
        record: plan,
        reference: plan.planId,
      },
    };
  }

  if (operation === "create-fixture") {
    const fixture = fixtureOutput(inputs);
    return {
      ...fixture,
      durable: {
        record: fixture,
        reference: fixture.fixtureId,
      },
    };
  }

  if (operation === "save-plan") {
    const planId = firstValue(inputs, ["planId", "create-edit-save-plan.draft.planId", "create-edit-save-plan.custom.planId"], "");
    const savedAt = timestamp();
    return {
      planId,
      savedAt,
      durable: {
        record: { planId, savedAt },
        reference: planId || null,
      },
    };
  }

  const plan = planOutput(inputs);
  const fixture = fixtureOutput(inputs);
  const authEmail = String(firstValue(inputs, ["authEmail", "create-edit-save-plan.draft.authEmail"], "")).trim();

  return {
    authEmail,
    signedIn: Boolean(authEmail),
    ...plan,
    ...fixture,
    durable: {
      record: { plan, fixture },
      reference: plan.planId,
    },
  };
}

