  { path: "/reports", name: "Reports", screenId: "reports-screen", Screen: MountedScreen4_reports_screen },
  { path: "/settings", name: "Settings", screenId: "settings-screen", Screen: MountedScreen5_settings_screen },
]);

function normalizePath(value) {
  const path = String(value || "/").split(/[?#]/)[0] || "/";
  return path.length > 1 ? path.replace(/\/+$/, "") : path;
}
function routeMatches(pattern, actual) {
  const wanted = normalizePath(pattern).split("/").filter(Boolean);
  const seen = normalizePath(actual).split("/").filter(Boolean);
  if (wanted.length !== seen.length) return false;
  return wanted.every((part, index) => part.startsWith(":") || part === "*" || part === seen[index]);
