  return <NavigationShell>{SCAFFOLD_ROUTES.map((route) => <a key={route.path} href={route.path}
    aria-current={routeMatches(route.path, path) ? "page" : undefined}
    onClick={(event) => { if (!event.metaKey && !event.ctrlKey && !event.shiftKey && event.button === 0) { event.preventDefault(); go(route.path, setPath); } }}>
    {route.name}</a>)}</NavigationShell>;
