  const [signingOut, setSigningOut] = useState(false);
  const [signedIn, setSignedIn] = useState(false);
  const [message, setMessage] = useState("Checking your Lumen Layouts account session…");
  const status = useStatusRegion({ label: "Account session status" });

  useEffect(() => {
    let active = true;

    async function loadAccount() {
      setLoadingAccount(true);
      try {
        const user = await currentUser();
        if (!active) return;
        setAccount(user || null);
        setSignedIn(Boolean(user));
        setMessage(
          user?.email
            ? `Settings page for signed-in account ${user.email}.`
            : "Sign-in panel is visible. No saved plan data is shown."
        );
      } catch (error) {
        if (!active) return;
        setAccount(null);
        setSignedIn(false);
        setMessage("Sign-in panel is visible. No saved plan data is shown.");
      } finally {
        if (active) setLoadingAccount(false);
      }
    }

    loadAccount();
    return () => {
      active = false;
    };
  }, []);

  const authEmail = account?.email || "";

  const accountInitial = useMemo(() => {
    if (!authEmail) return "LL";
    return authEmail.slice(0, 2).toUpperCase();
  }, [authEmail]);

  async function handleSignOut() {
    setSigningOut(true);
    setMessage("Signing out and clearing the visible authenticated session…");

    try {
      const boundaryResult = await runSettingsAndSignOutBoundaryCustomBehavior(
        { authEmail, signedIn },
        { operation: "sign-out" }
      );

      await signOut();

      setAccount(null);
      setSignedIn(Boolean(boundaryResult?.signedIn));
      setMessage("Signed out. The signed-out home or sign-in screen is visible.");
      navigate("/");
    } catch (error) {
      setMessage(error?.message || "Sign out could not be completed. Please try again.");
    } finally {
      setSigningOut(false);
    }
  }

  const signOutAction = useSemanticAction({
    name: "sign-out",
    label: "sign-out control",
    onActivate: handleSignOut,
  });

  return (
    <section data-scaffold-slot="settings-screen" className="min-h-screen bg-slate-950 text-slate-100">
      <div className="mx-auto flex w-full max-w-6xl flex-col gap-8 px-6 py-8 lg:px-10">
        <header className="rounded-[2rem] border border-cyan-300/20 bg-slate-900/90 p-8 shadow-2xl shadow-cyan-950/30">
          <div className="flex flex-col gap-6 md:flex-row md:items-center md:justify-between">
            <div>
              <p className="text-sm font-semibold uppercase tracking-[0.35em] text-cyan-300">Lumen Layouts</p>
              <h1 className="mt-3 text-4xl font-black tracking-tight text-white">Account settings</h1>
              <p className="mt-3 max-w-2xl text-base leading-7 text-slate-300">
                Verify the signed-in account boundary, manage access to protected planning routes, and end the
                current authenticated session before sharing this device.
              </p>
            </div>
            <RouteLink
              to="/workspace"
              className="inline-flex items-center justify-center rounded-full border border-cyan-300/40 px-5 py-3 text-sm font-bold text-cyan-100 transition hover:bg-cyan-300/10"
            >
              Return to workspace
            </RouteLink>
          </div>
        </header>

        <div className="grid gap-6 lg:grid-cols-[1fr_0.9fr]">
          <article className="rounded-[1.5rem] border border-white/10 bg-white/[0.06] p-6 shadow-xl shadow-slate-950/40">
            <div className="flex items-start gap-4">
              <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-2xl bg-cyan-300 text-xl font-black text-slate-950">
                {accountInitial}
              </div>
              <div className="min-w-0 flex-1">
                <p className="text-sm font-semibold uppercase tracking-[0.24em] text-slate-400">Signed-in account</p>
                {loadingAccount ? (
                  <p className="mt-2 text-2xl font-bold text-white">Loading account…</p>
                ) : authEmail ? (
                  <p className="mt-2 break-words text-2xl font-bold text-white">{authEmail}</p>
                ) : (
                  <p className="mt-2 text-2xl font-bold text-white">Signed-out home or sign-in screen is visible</p>
                )}
                <p className="mt-3 text-sm leading-6 text-slate-300">
                  {authEmail
                    ? "This email identifies the backend SDK user whose saved plans, reports, and workspace data are currently visible."
                    : "You are signed out. Protected routes such as the workspace should show the sign-in panel and no saved plan data."}
                </p>
              </div>
            </div>

            <div className="mt-6 rounded-2xl border border-slate-700 bg-slate-950/60 p-4">
              <h2 className="text-lg font-bold text-white">Session boundary</h2>
              <p className="mt-2 text-sm leading-6 text-slate-300">
                Use the sign-out control to clear the visible authenticated session and return protected pages to
                the sign-in state.
              </p>
              <button
                {...signOutAction.buttonProps}
                type="button"
                data-thrallo-action="act_f1fcf21d"
                disabled={signingOut || loadingAccount || !signedIn}
                className="mt-5 inline-flex w-full items-center justify-center rounded-full bg-cyan-300 px-5 py-3 text-sm font-black text-slate-950 transition hover:bg-cyan-200 disabled:cursor-not-allowed disabled:bg-slate-700 disabled:text-slate-400 md:w-auto"
              >
                {signingOut ? "Signing out…" : "sign-out control"}
              </button>
            </div>

            <div {...status.statusProps} className="mt-5 rounded-2xl border border-cyan-300/20 bg-cyan-300/10 p-4 text-sm font-semibold text-cyan-100">
              {message}
            </div>
          </article>

          <aside className="rounded-[1.5rem] border border-white/10 bg-slate-900 p-6">
            <h2 className="text-xl font-black text-white">Protected route check</h2>
            <p className="mt-3 text-sm leading-6 text-slate-300">
              After signing out, opening the workspace route while signed out must display the sign-in panel and no
              saved plan data. These links let you verify that boundary without exposing private plan content here.
            </p>
            <div className="mt-5 grid gap-3">
              <RouteLink to="/" className="rounded-2xl border border-slate-700 px-4 py-3 text-sm font-bold text-slate-100 hover:bg-white/10">
                Open signed-out home
              </RouteLink>
              <RouteLink to="/workspace" className="rounded-2xl border border-slate-700 px-4 py-3 text-sm font-bold text-slate-100 hover:bg-white/10">
                Open workspace route
              </RouteLink>
            </div>
          </aside>
        </div>

        <div className="sr-only" aria-hidden="true">
          <CreateEditSavePlanFlow />
        </div>
      </div>
    </section>
  );
}

